INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (7001, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 7, 106001, -363.0, "キャル", 0, "たまには\n協力するのもいいんじゃない？\nあたしも手を貸してあげる");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (7002, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 7, 105901, -363.0, "コッコロ", 0, "多くの方と協力して\n戦えるようです\n主さまなら、さぞ\nご活躍なさることでしょう");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (7003, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 7, 105801, -363.0, "ペコリーヌ", 0, "たくさんの人と一緒に\n協力バトルです！\nがんばりましょう☆");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (10001, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 10, 105801, -363.0, "ペコリーヌ", 0, "ジュエルを食べ物…\nいえ、貴重品と交換できます！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (10002, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 10, 106001, -363.0, "キャル", 0, "ジュエルはよく考えて\n使うことね\n無駄遣い厳禁！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (10003, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 10, 105901, -363.0, "コッコロ", 0, "主さまのジュエルで\n貴重な品々を購入できます\nですが、無駄遣いは\n『めっ』でございますよ");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (10004, 2104010, 0.0, 1, 1, "2030/12/17 14:59:59", 2, "2015/12/17 15:00:00", 0.0, 10, 106401, -363.0, "シェフィ", 0, "ジュエルがあれば\n貴重品と交換できるみたい\n大事に使いましょうね");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (12001, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 12, 105801, -416.5, "ペコリーヌ", 0, "特定の条件を達成すると\n報酬がもらえますよ！\nがんばりましょう♪　");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (13001, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 13, 106001, -363.0, "キャル", 0, "思い出が詰まってるって\nいろいろあったけど\n振り返るのもいいんじゃない？");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (13002, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 13, 105901, -363.0, "コッコロ", 0, "主さまとの楽しい日々…\nこちらで何度でも\n思い返しましょう♪");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (13003, 2104010, 0.0, 1, 1, "2030/12/17 14:59:59", 2, "2015/12/17 15:00:00", 0.0, 13, 106401, -363.0, "シェフィ", 0, "みんなとの大切な思い出が\nたくさん詰まってるのね\n一緒に振り返って、\n心に刻みたいわ");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (13004, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 13, 105801, -363.0, "ペコリーヌ", 0, "女の子との思い出が\nたくさん見られますよ！\nヒューヒュー♪\nモテモテですねー☆");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (14001, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 14, 105901, -363.0, "コッコロ", 0, "育成に必要なアイテムが\n獲得できるクエストです\nわたくし、主さまのために、\n強くなりますよ");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (14002, 2104010, 0.0, 1, 1, "2030/12/17 14:59:59", 2, "2015/12/17 15:00:00", 0.0, 14, 106401, -363.0, "シェフィ", 0, "このクエストを攻略すると、\nアイテムが手に入るらしいわ。\nもっと強くなるために、\n一生懸命がんばるわね！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (14003, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 14, 105801, -363.0, "ペコリーヌ", 0, "このクエストを攻略すれば、\nアイテムがもらえますよ\nたくさん集めて、どんどん\n強くなっちゃいましょう！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (14004, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 14, 106001, -363.0, "キャル", 0, "クエストを攻略すると、\nアイテムが手に入るんだって\nもらえるものは、\nもらっておきましょ！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (15001, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 15, 105901, -470.0, "コッコロ", 0, "主さま、旅の準備を整えて\nより充実した冒険をいたし\nましょう");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (16001, 2104010, 0.0, 1, 1, "2030/12/17 14:59:59", 2, "2015/12/17 15:00:00", 0.0, 16, 106401, -363.0, "シェフィ", 0, "ねぇ…クランに加入してみない？\n一人も楽しいけど、みんなと\n一緒も賑やかでいいと思うの");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (16002, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 16, 105801, -363.0, "ペコリーヌ", 0, "クランに加入してみませんか？\nみんなといっしょに冒険した方が、\n楽しいですよ！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (16003, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 16, 106001, -363.0, "キャル", 0, "クランに入れるらしいわよ\nせっかくだから入ってみたら？\nけっこう楽しいみたいよ♪");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (16004, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 16, 105901, -363.0, "コッコロ", 0, "こちらでクランに加入できます\n素敵なクランがたくさんあって、\n目移りしてしまいますね");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (17002, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 17, 105901, -363.0, "コッコロ", 0, " こちらではクランバトルに\n 参加された仲間のみなさんの\n 活躍を振り返ることができます");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (17004, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 25, 106001, -363.0, "キャル", 0, "模擬戦の戦績もアンタが\n気に入ったものがあれば\n記録しておけるのね");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (17005, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 25, 105901, -363.0, "コッコロ", 0, "主さま、今回のクランバトルでの\nご活躍が記録されています\nバトルの参考にいたしましょう");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (17006, 2104010, 0.0, 1, 1, "2030/12/17 14:59:59", 2, "2015/12/17 15:00:00", 0.0, 25, 106401, -363.0, "シェフィ", 0, "今回のクランバトルの調子は\nどうかしら？\n戦績を見れば、次のバトルに\n活かせるかもしれないわ");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (17007, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 25, 105801, -363.0, "ペコリーヌ", 0, "今回のクランバトルでの戦績を\nおさらいできますよ！\n私にも見せてください☆");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (18001, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 18, 190801, -363.0, "カリン", 0, "ようこそ！\nこちらでは、\nギルドハウスで流れる音楽の\n変更や購入が出来ますよ");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (18002, 0, 0.0, 2, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 18, 190801, -363.0, "カリン", 0, "ＢＧＭの変更や購入は、こちらから\nできますよ\n素敵な音楽を、たくさんご用意\nいたしました！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (19001, 0, 0.0, 3, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 19, 190801, -470.0, "カリン", 0, "ギルドハウスの\nＢＧＭを変更できますよ\nあなたの好きな曲、\n私にも聴かせてくださいね");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (19002, 0, 0.0, 4, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 19, 190801, -470.0, "カリン", 0, "こちらでは、ＢＧＭの変更が\nできますよ\nどんな曲に変更しますか？\nふふふ、私も楽しみです♪");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (20001, 0, 0.0, 5, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 20, 190801, -470.0, "カリン", 0, "こちらでは、ＢＧＭを購入\nすることができますよ\n試聴することもできるので、\nじっくり選んでくださいね");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (20002, 0, 0.0, 6, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 20, 190801, -470.0, "カリン", 0, "いらっしゃいませ！\nＢＧＭの購入はこちらです\n素敵な曲がたくさんあって、\n目移りしちゃいますね");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (21001, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 21, 106001, -363.0, "キャル", 0, "ここで手に入れたアイテムで\n専用装備を作成できるみたいね\nアイテムが集まったら\nさっそく作ってみましょ！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (21002, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 21, 105901, -363.0, "コッコロ", 0, "攻略すると珍しいアイテムが\n手に入りますよ\nこのアイテムで専用装備を\n作成できるようです");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (21003, 2104010, 0.0, 1, 1, "2030/12/17 14:59:59", 2, "2015/12/17 15:00:00", 0.0, 21, 106401, -363.0, "シェフィ", 0, "専用装備が欲しいなら\nこのクエストに挑戦するといいわ\n集めた素材でもっともっと\n強くなりましょう");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (21004, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 21, 105801, -363.0, "ペコリーヌ", 0, "専用装備の作成に必要な\nアイテムを獲得できますよ\nたくさん集めてどんどん\n強くなりましょう！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (22001, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 22, 190801, -430.0, "カリン", 0, "投票はこちらです\nあなたが応援したい女の子に\n思いを込めた一票を\nお願いします！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (22002, 0, 0.0, 2, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 22, 190801, -430.0, "カリン", 0, "ようこそ！\nあなたが思いを寄せるのは\nどの女の子ですか？\n応援してあげてくださいね！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (23001, 0, 0.0, 3, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 23, 190801, -430.0, "カリン", 0, "たくさんの投票、\nありがとうございました\n結果発表を楽しみに\n待っていてくださいね！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (23002, 0, 0.0, 4, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 23, 190801, -430.0, "カリン", 0, "ただ今、人気投票の\n集計中です\n結果が出るまでもう少しだけ\nお待ちくださいね");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24001, 0, 4.08, 1, 2, "2030/12/17 14:59:59", 1, "2019/01/31 12:00:00", 8.0, 24, 109001, -385.0, "エリコ（バレンタイン）", 10011, "あなた様が手伝ってくださった\nチョコレートケーキ\n美味しくないはずがありませんわ");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24002, 0, 5.0, 2, 2, "2030/12/17 14:59:59", 1, "2019/01/31 12:00:00", 8.0, 24, 109001, -385.0, "エリコ（バレンタイン）", 10011, "このような失敗、あなた様が\nするはずありません\nもう一度挑戦してみましょう");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24003, 0, 10.11, 3, 2, "2030/12/17 14:59:59", 1, "2019/01/31 12:00:00", 8.0, 24, 109001, -385.0, "エリコ（バレンタイン）", 10011, "あなた様のために\n作っているケーキを\nあなた様に手伝っていただく……\nことになるなんて……クスクス");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24004, 0, 4.0, 4, 2, "2030/12/17 14:59:59", 1, "2019/01/31 12:00:00", 8.0, 24, 109001, -385.0, "エリコ（バレンタイン）", 10011, "あまり気に病む必要はありませんわ\nこれからは私がたっぷりと\n時間をかけて教えて差し上げますから");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24005, 0, 6.0, 5, 2, "2030/12/17 14:59:59", 1, "2019/01/31 12:00:00", 8.0, 24, 109001, -385.0, "エリコ（バレンタイン）", 10011, "今回は調子が悪かった……のですか？\nあなた様が手伝ってくれたものなら\nわたしはどんなものでも……クスクス");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24006, 0, 0.0, 6, 1, "2030/12/17 14:59:59", 1, "2019/01/31 12:00:00", 0.0, 24, 109002, 0.0, "エリコ（バレンタイン）", 10011, "あなた様が手がけた\nチョコレートケーキは\n私にとっての宝物……\n侮辱する者は生かしておきませんわ");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24007, 0, 0.0, 7, 1, "2030/12/17 14:59:59", 1, "2019/01/31 12:00:00", 0.0, 24, 109002, 0.0, "エリコ（バレンタイン）", 10011, "とても素晴らしい出来栄えですわ！\nあなた様にふさわしい\nチョコレートケーキができました");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24008, 0, 0.0, 8, 1, "2030/12/17 14:59:59", 1, "2019/01/31 12:00:00", 0.0, 24, 109002, 0.0, "エリコ（バレンタイン）", 10011, "私を手伝ってくれたあなた様は\nすでに私の虜……\n甘い世界に誘って差し上げますわ");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24009, 0, 0.0, 9, 1, "2030/12/17 14:59:59", 1, "2019/01/31 12:00:00", 0.0, 24, 109002, 0.0, "エリコ（バレンタイン）", 10011, "あなた様の愛情\nしかと受け止めました\nこれが……私たちの初めての\n共同作業ですわね……クスクス");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24010, 0, 0.0, 10, 1, "2030/12/17 14:59:59", 1, "2019/01/31 12:00:00", 0.0, 24, 109002, 0.0, "エリコ（バレンタイン）", 10011, "これは世界一の\nチョコレートケーキですわ\nだって、あなた様が腕によりをかけて\n作ってくださったんですもの");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24011, 0, 2.12, 1, 2, "2030/12/17 14:59:59", 1, "2019/01/31 12:00:00", 8.0, 24, 109101, -385.0, "シズル（バレンタイン）", 10011, "上手にできなくて残念だった？\nでも、弟くんの気持ちが嬉しいな\nいつだってお姉ちゃんは\nそばにいるからね♪");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24012, 0, 4.19, 2, 2, "2030/12/17 14:59:59", 5, "2019/01/31 12:00:00", 8.0, 24, 109101, -385.0, "シズル（バレンタイン）", 10011, "うーん、弟くんには珍しく\n緊張しちゃったのかな？\nもう一度チャレンジしてみる？");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24013, 0, 2.3, 3, 4, "2030/12/17 14:59:59", 2, "2019/01/31 12:00:00", 8.0, 24, 109101, -385.0, "シズル（バレンタイン）", 10011, "お姉ちゃんのお手伝い、\nよくできました！\nあー、\nまだつまみ食いしちゃダメだぞ！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24014, 0, 0.0, 4, 1, "2030/12/17 14:59:59", 1, "2019/01/31 12:00:00", 0.0, 24, 109102, 0.0, "シズル（バレンタイン）", 10011, "見てみて！\nスポンジに綺麗な焼き目がついてるよ\nさっすが弟くんだね！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24015, 0, 5.23, 5, 2, "2030/12/17 14:59:59", 5, "2019/01/31 12:00:00", 8.0, 24, 109101, -385.0, "シズル（バレンタイン）", 10011, "まぁまぁ、落ち込まないで\n見た目は……個性的だけど、\n味は絶対美味しいはずだから！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24016, 0, 0.0, 6, 1, "2030/12/17 14:59:59", 1, "2019/01/31 12:00:00", 0.0, 24, 109102, 0.0, "シズル（バレンタイン）", 10011, "弟くんみたいな\n可愛いケーキができたよ！\n早く食べてみたいでしょ♪");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24017, 0, 5.01, 7, 2, "2030/12/17 14:59:59", 1, "2019/01/31 12:00:00", 8.0, 24, 109101, -385.0, "シズル（バレンタイン）", 10011, "あれれ？　弟くん、指に\nチョコレートがくっついてるよ？\nお姉ちゃんが舐めてあげるね、\nはぁむ！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24018, 0, 0.0, 8, 1, "2030/12/17 14:59:59", 1, "2019/01/31 12:00:00", 0.0, 24, 109102, 0.0, "シズル（バレンタイン）", 10011, "なかなか上手にできたんじゃない？\nでも弟くんはまだまだできる子！\nお姉ちゃん、信じてるからね");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24019, 0, 0.0, 9, 1, "2030/12/17 14:59:59", 1, "2019/01/31 12:00:00", 0.0, 24, 109102, 0.0, "シズル（バレンタイン）", 10011, "わぁ～、\nとっても美味しそうにできたね！\n弟くん手慣れてたから\nお姉ちゃん安心して任せられちゃった！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24020, 0, 0.0, 10, 1, "2030/12/17 14:59:59", 1, "2019/01/31 12:00:00", 0.0, 24, 109102, 0.0, "シズル（バレンタイン）", 10011, "や～ん、弟くんが手伝ってくれた\nチョコレートケーキ！\nすっごく美味しそうにできたね♪");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (26001, 2104010, 0.0, 1, 1, "2030/12/17 14:59:59", 2, "2015/12/17 15:00:00", 0.0, 26, 106401, -363.0, "シェフィ", 0, "ここから先は神聖な場所みたい\nどんなお宝が眠っているのか、\n今から探索するのが楽しみね♪");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (26002, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 26, 105801, -363.0, "ペコリーヌ", 0, "ここから先は神聖な場所\nみたいです！\nどんなお宝が手に入るか\n楽しみですね！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (26003, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 26, 106001, -363.0, "キャル", 0, "この先は神聖な場所みたい。\n手に入るお宝も並じゃないけど\n気を付けていかないと\n痛い目にあうわよ");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (26004, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 26, 105901, -363.0, "コッコロ", 0, "ここから先は神聖な場所\nでございます。\n気を引き締めてお宝の\n調査探索に参りましょう");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (27001, 2104010, 0.0, 1, 1, "2030/12/17 14:59:59", 2, "2015/12/17 15:00:00", 0.0, 27, 106401, -363.0, "シェフィ", 0, "ここにさらなる力を得るための\nアイテムが眠っている…って\nみんな言ってるわ。ふふっ、\nそれじゃあ挑戦してみましょうか");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (27002, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 27, 105801, -363.0, "ペコリーヌ", 0, "ここにさらなる力を得るための\nアイテムが眠っているみたい\nです！　どこから挑戦するか\n迷っちゃいますね！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (27003, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 27, 106001, -363.0, "キャル", 0, "ここにさらなる力を得るための\nアイテムが眠っているみたい！\nどんどん挑戦して\n強くなっちゃいましょ！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (27004, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 27, 105901, -363.0, "コッコロ", 0, "こちらにさらなる力を得る\nためのアイテムが眠っている\nようです。主さま、どこから\n挑戦いたしましょう。");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (28001, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2019/09/24 15:00:00", 0.0, 28, 190801, -363.0, "カリン", 0, "ようこそ！\n皆さんの素敵な出会いを\nギルド管理協会が\nお手伝いします！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (28002, 0, 0.0, 2, 1, "2030/12/17 14:59:59", 1, "2019/09/24 15:00:00", 0.0, 28, 190801, -363.0, "カリン", 0, "ギルド管理協会です\nフレンドに関しては\nこちらでご確認ください");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (29001, 0, 0.0, 3, 1, "2030/12/17 14:59:59", 1, "2019/09/24 15:00:00", 0.0, 29, 190801, -409.0, "カリン", 0, "こちらがフレンドの\n皆さんです\n素敵な関係を\n築いてくださいね！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (29002, 0, 0.0, 4, 1, "2030/12/17 14:59:59", 1, "2019/09/24 15:00:00", 0.0, 29, 190801, -409.0, "カリン", 0, "こちらの一覧で\nフレンドのプロフィールを\n確認できますよ");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (30001, 0, 0.0, 5, 1, "2030/12/17 14:59:59", 1, "2019/09/24 15:00:00", 0.0, 30, 190801, -409.0, "カリン", 0, "フレンド管理は\nこちらになります\n新しいフレンドとの出会いを\n楽しんでくださいね！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (30002, 0, 0.0, 6, 1, "2030/12/17 14:59:59", 1, "2019/09/24 15:00:00", 0.0, 30, 190801, -409.0, "カリン", 0, "フレンドの申請や\n承認ができますよ\nどうぞ、良き交流を！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (31001, 0, 0.0, 7, 1, "2030/12/17 14:59:59", 1, "2019/10/31 12:00:00", 0.0, 31, 190801, -409.0, "カリン", 0, "バトルをして力比べを\nしてみましょう！\n実力が試されますね、\n頑張ってください！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (31002, 0, 0.0, 8, 1, "2030/12/17 14:59:59", 1, "2019/10/31 12:00:00", 0.0, 31, 190801, -409.0, "カリン", 0, "気になるパーティと\nバトルをしてみましょう！\nどちらが勝利するのか、\n私も楽しみにしていますね");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (32001, 0, 0.0, 1, 1, "2020/01/04 4:59:59", 1, "2019/12/20 5:00:00", 0.0, 32, 190801, -409.0, "カリン", 0, "ルーキーの皆さんのために\n特別なミッションを\nご用意いたしました！\nぜひ、挑戦してください！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (32002, 0, 0.0, 2, 1, "2020/01/04 4:59:59", 1, "2019/12/20 5:00:00", 0.0, 32, 190801, -409.0, "カリン", 0, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (33001, 0, 0.0, 3, 1, "2020/01/04 4:59:59", 1, "2019/12/20 5:00:00", 0.0, 33, 190801, -409.0, "カリン", 0, "フレンドになって\n初心者の方を応援しましょう！\n素敵な報酬が待っていますよ！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (33002, 0, 0.0, 4, 1, "2020/01/04 4:59:59", 1, "2019/12/20 5:00:00", 0.0, 33, 190801, -409.0, "カリン", 0, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (34001, 0, 0.0, 5, 1, "2020/01/10 11:59:59", 1, "2020/01/04 5:00:00", 0.0, 34, 190801, -409.0, "カリン", 0, "お疲れ様でした！\nミッションの報酬の受け取りは\nこちらからできますよ！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (34002, 0, 0.0, 6, 1, "2020/01/10 11:59:59", 1, "2020/01/04 5:00:00", 0.0, 34, 190801, -409.0, "カリン", 0, "ミッション報酬の受け取りは\nこちら！\n受け取り漏れの無いように\n気を付けてくださいね！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (38001, 0, 5.3, 1, 2, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 38, 105801, -458.0, "ペコリーヌ", 0, "過去のストーリーイベントを\n楽しめちゃいますよ！\n遊んだことのないものがあれば\n一緒にやってみましょう♪");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (38002, 0, 6.5, 2, 2, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 38, 105801, -458.0, "ペコリーヌ", 0, "これまでのイベントで登場した\n限定キャラを仲間にできたり\nメモリーピースが手に入る\nみたいですよ。やばいですね☆");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (39005, 0, 0.0, 0, 3, "2020/04/08 23:59:59", 3, "2020/04/01", 9999.0, 39, 105801, 9999.0, "ペコリーヌ", 0, "");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (40001, 0, 0.0, 2, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 40, 190801, -430.0, "カリン", 0, "これまでに出題された\n問題を振り返ることが\nできますよ\n復習は大切です♪");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (41001, 2104010, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 41, 106401, -363.0, "シェフィ", 0, "ここでは腕試しが\nできるんですって。\n自分の実力を測るのに、\nちょうどよさそうね。");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (41002, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 41, 105801, -363.0, "ペコリーヌ", 0, "ここで腕試しを\nしていきましょう！\n全力全開、\nがんばっちゃいますよ～！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (41003, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 41, 106001, -363.0, "キャル", 0, "ここで腕試しが\nできるみたいね。\n試してみるのも\nいいんじゃない？");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (41004, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 41, 105901, -363.0, "コッコロ", 0, "腕試しができるようです。\nここで練習を重ね、実戦に\n活かしてまいりましょう。");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (42001, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 42, 105901, -416.5, "コッコロ", 0, "訓練の成果に応じて、\n報酬がもらえるそうです。\n共に励んでいきましょう。");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (42002, 2104010, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 42, 106401, -416.5, "シェフィ", 0, "目標を達成すれば、\n報酬がもらえるみたい。\n頑張り甲斐があるわね。");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (42003, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 42, 105801, -416.5, "ペコリーヌ", 0, "腕試しをがんばれば、\n報酬がもらえますよ。\n挑戦していきましょう☆");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (42004, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 42, 106001, -416.5, "キャル", 0, "ミッションを達成すると、\n報酬が出るんですって。\n一緒にやってみましょ！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (43001, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 43, 105801, -363.0, "ペコリーヌ", 0, "ここからアリーナに\n挑戦できますよ！\n編成を工夫してライバルに\n挑んじゃいましょう！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (43002, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 43, 105901, -363.0, "コッコロ", 0, "こちらからアリーナに\n挑戦することができます。\n主さまらしい編成で\nライバルに挑みましょう。");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (43003, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 43, 106001, -363.0, "キャル", 0, "ここからアリーナに\n挑戦できるわよ！\nしっかり編成を考えて\nライバルに挑みなさい！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (43004, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 44, 123001, -416.5, "アメス", 0, "ミッションをクリアすると報酬が\n受け取れるわ。ジャンジャン\nクリアしてバリバリ強化して\nあげなさい♪");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (43005, 0, 0.0, 2, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 44, 123001, -416.5, "アメス", 0, "ぼんやりしてる場合じゃないわ。\n早くミッションをクリアして\n報酬を受け取ってきなさい！");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (43006, 0, 5.79, 3, 2, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 45, 123001, -416.5, "アメス", 0, "ちょっとあんた、報酬が\n受け取れるじゃない！\n忘れずにチェックなさい。\nアメス様との約束よ？");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (46001, 0, 0.0, 1, 1, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 46, 123001, -371.5, "アメス", 0, "はい、お疲れさま。\nここではマスタリーチケットを\n使って、マスタリー強化素材を\n手に入れることができるわよ。");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (47001, 0, 0.0, 1, 2, "2030/12/17 14:59:59", 2, "2015/12/17 15:00:00", 0.0, 47, 104901, -416.5, "シズル", 0, "呼ばれて飛び出てお姉ちゃんだよ♪\nたとえ火の中、水の中、迷宮の中っ\nこのダンジョンを踏破できるよう\n弟くんを応援してあげるからねっ♪");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (47002, 0, 9.32, 1, 2, "2030/12/17 14:59:59", 1, "2015/12/17 15:00:00", 0.0, 47, 101101, -416.5, "リノ", 0, "ほんとーに不思議な場所ですね～\nお兄ちゃんが冒険を頑張れるよう\nおまじないをかけてあげますねっ\nフレーフレー、お・兄・ちゃんっ♪");
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (48001, 0, 0.0, 0, 2, "2030/12/17 14:59:59", 2, "2015/12/17 15:00:00", 0.0, 48, 104901, -470.0, "シズル", 0, "");
